INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1529', '気になってる人が男じゃなかった', '2027年冬', 'PR0046', 'TVシリーズ', NULL, '『気になってる人が男じゃなかった』（きになってるひとがおとこじゃなかった）は、新井すみこによる日本の漫画作品。 2022年4月10日より作者である新井のTwitterで連載され、2023年にはKADOKAWAより単行本が発売されている。『ダ・ヴィンチ』（KADOKAWA）2023年10月号のSNS漫画特集で描き下ろし作品が掲載された。 「次にくるマンガ大賞2023」Webマンガ部門で1位を獲得。「', 186822) ON CONFLICT DO NOTHING;
