INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1535', 'ヒストリエ', '2027年冬', 'PR0058', 'TVシリーズ', NULL, '『ヒストリエ』（HISTORIĒ）は、岩明均による歴史漫画。『月刊アフタヌーン』（講談社）にて、2003年3月号から連載中。作者がデビュー前から構想を温めていた作品である。 2026年1月時点で累計発行部数は470万部を突破している。 2026年1月にテレビアニメ化が発表された。2027年1月より放送予定。', 205130) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1536', '魔入りました！入間くん if Episode of 魔フィア', '2027年冬', NULL, 'TVシリーズ', NULL, NULL, 207251) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1537', '姫騎士様のヒモ', '2027年冬', 'PR0008', 'TVシリーズ', NULL, '『姫騎士様のヒモ』（ひめきしさまのヒモ）は、白金透による日本のライトノベル。イラストはマシマサキが担当している。電撃文庫（KADOKAWA）より2022年2月から刊行されている。第28回電撃小説大賞大賞受賞作。2025年5月時点で、電子版も含めたシリーズ累計発行部数は20万部を突破している。 メディアミックスとして、きぃやんによる原作1巻のコミカライズがComicWalker（現・カドコミ）にて2', 186741) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1538', '一式さんは恋を知りたい。', '2027年冬', NULL, 'TVシリーズ', NULL, '『一式さんは恋を知りたい。』（いっしきさんはこいをしりたい）は、あららぎあゆねによる日本の漫画。同作者の作品『リンナ警部は呼吸ができない』のリブート作品である。『月刊少年エース』（KADOKAWA）において、2020年8月号（6月26日発売）から連載中。連載開始時のタイトルは『鋼鉄のリンナは××されたい』であり、3話目から現在のタイトルに変更された。 2025年にはテレビアニメ化が発表された。', 200578) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1539', '結界師の一輪華', '2027年冬', 'PR0081', 'TVシリーズ', NULL, '『結界師の一輪華』（けっかいしのいちりんか）は、クレハによる日本の小説。イラストはボダックスが担当している。角川文庫（KADOKAWA）より2021年12月から刊行されている。2025年8月時点でシリーズ累計部数は200万部を突破している。 メディアミックスとしておだやかによるコミカライズ版が『B''s-LOG COMIC』（同社）にてVol.110（2022年3月5日発売）より連載されている。また', 197619) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1540', 'ゾンビのあふれた世界で俺だけが襲われない', '2027年冬', NULL, 'TVシリーズ', NULL, '『ゾンビのあふれた世界で俺だけが襲われない』（ゾンビのあふれたせかいでおれだけがおそわれない）は、裏地ろくろによる日本の新文芸・ジュブナイルポルノ。元々は小説投稿サイト「小説家になろう」の成人向け姉妹サイト「ノクターンノベルズ」にて2013年1月9日より裏路地の名義で連載されていた。2017年2月時点で第3章まで連載され、その後は更新が停止している。書籍版は「ノクスノベルス」（フロンティアワークス', 174427) ON CONFLICT DO NOTHING;
