INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1550', 'カリスマ', '2027年冬', 'PR0090', 'TVシリーズ', NULL, 'カリスマ（ギリシア語: Χάρισμα、ドイツ語: Charisma）とは、超自然的・超人間的・非日常的な資質や能力。神の賜物または天賦の力で、教祖・預言者・呪術師・英雄などに見られるとされる。『オックスフォード現代英英辞典』（Oxford Advanced Learner''s Dictionary）では、カリスマ（charisma）は「一部の人々が持つ、他の人々を引きつけ感銘を与える強力な個人の', 203116) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1551', '傷口と包帯', '2027年冬', 'PR0006', 'TVシリーズ', NULL, NULL, 214049) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1552', 'カグラバチ', '2027年春', 'PR0174', 'TVシリーズ', NULL, '『カグラバチ』は、外薗健による日本の漫画作品。『週刊少年ジャンプ』（集英社）において、2023年42号から連載中。漢字表記は「神楽鉢」。父を殺された少年が父の遺した妖刀を手に復讐を誓う剣戟バトルアクション漫画。', 211496) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1553', '薬屋のひとりごと 第3期 第2クール', '2027年春', 'PR0034', 'TVシリーズ', NULL, NULL, 200927) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1554', '幼稚園WARS', '2027年春', 'PR0102', 'TVシリーズ', NULL, '『幼稚園WARS』（ようちえんウォーズ）は、千葉侑生による日本の漫画作品。『少年ジャンプ+』（集英社）にて、2022年9月15日から連載中。ジャンプルーキー!の連載争奪ランキングにて読者投票によりインディーズとして連載開始。21話より通常連載へと移行した作品である。 作者の千葉によると、本作は「『殺し屋×幼稚園』のラブコメ」であり、「イケメン好きの最強先生と次々に攻めてくるイケメン殺し屋のイカれた', 199597) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1555', 'LONA', '2027年春', 'PR0078', 'TVシリーズ', NULL, NULL, 213655) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1556', '運命の巻戻士', '2027年春', 'PR0121', 'TVシリーズ', NULL, '『運命の巻戻士』（うんめいのまきもどし）は、木村風太による日本の漫画作品。『月刊コロコロコミック』（小学館）2021年9月号の読み切り掲載を経て、同誌2022年2月号から連載中。「SFループ漫画」を称する。2026年には第71回小学館漫画賞を受賞。 メディアミックスとして、連載開始同年よりYouTubeにてデジタルコミック形式のWebアニメ（制作：ケイコンテンツ）を配信するほか、2025年にテレビ', 195787) ON CONFLICT DO NOTHING;
