INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH013981', 'AN1528', '坂本太郎', '坂本太郎は引退した殺し屋だ。彼はかつて、世界中の悪党や殺し屋たちから恐れられ、畏敬の念を抱かれる最高の殺し屋だった。 しかし、彼は妻と一緒にいるために殺し屋の世界を去った。現在は店を経営しており、子供も一人いる。彼は町の何でも屋として知られ、町の人々から非常に人気があり、親しまれている。', 27, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b196522-phOzXgufOs7R.png', '11月21日', NULL, '杉田智和', 188, 196522, 'MAIN', 1850) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH013982', 'AN1528', '朝倉シン', 'シンは、元殺し屋で、現在は坂本の部下として働いている。彼は周囲の人々の思考を聞き取る能力を持っている。', 20, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b196521-bedknWj9u7s2.png', '6月7日', NULL, '島﨑信長', 172, 196521, 'MAIN', 1418) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH013983', 'AN1528', '四ツ村暁', 'かつて「オーダー」の一員だったが、同組織から追放された後、現在はJAAと対立している。神々廻の先輩にあたる。四ツ村は、現存する暗殺者の中でも最強クラスの一人であり、現役のオーダーメンバー3人（神々廻、南雲、大佐木）を相手に、単独で互角に戦える実力を見せている。 彼は、片端に細く小さな刃が付いた三節棍を操る。その刃は驚異的な切れ味を持ち、人間の体を丸ごと切り裂くことができる。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b288348-9ufKqfp0LpXe.png', NULL, NULL, '藤真秀', NULL, 288348, 'SUPPORTING', 61) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH013984', 'AN1528', '周ツ村周', 'ジャパン・クリア・クリエーション（JCC）のアサシン専攻2年生。元オーダーのメンバーである四ツ村暁の息子。祖父はJCCで用務員として働いている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b288220-mrdBJVsFTGAo.png', '3月14日', 'A', '戸谷菊之介', NULL, 288220, 'SUPPORTING', 40) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH013985', 'AN1528', '神々廻', '神々廻は暗殺者であり、「ザ・オーダー」の一員である。ザ・オーダーとは、日本暗殺者協会（JAA）内の秩序を維持することを使命とする、強力な暗殺者たちの集団である。彼の愛用する武器はクローハンマーである。', 26, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b272879-pNkWPepupu3X.png', '9月24日', NULL, NULL, 180, 272879, 'SUPPORTING', 363) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH013986', 'AN1528', '南雲', '南雲は坂本の旧知の友人である。彼はJAAで最高位の暗殺者集団「ザ・オーダー」の一員だ。初登場シーンでは、坂本を訪ね、彼に懸賞金について知らせる場面が描かれている。', 27, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b264336-W5eQn2SL4P7N.png', '7月9日', NULL, '花江夏樹', 190, 264336, 'SUPPORTING', 2145) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH013987', 'AN1528', '勢羽夏生', 'オクタビ研究所の元職員であり、同研究所の最新かつ最も成功した被験者の一人でもある。 現在はJCCの学生であり、同校の武器生産部門のリーダーを務めている。セバは、特殊な黒色のスーツを身にまとっており、それ（あるいはその素材で覆われているもの）によって、意のままに姿を消すことができる。彼はマフユの兄である。', 20, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b288223-WzVqsLrhoS4Z.jpg', '7月2日', NULL, '岡本信彦', NULL, 288223, 'SUPPORTING', 335) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH013988', 'AN1528', '赤尾晶', '赤尾晶は、JCC試験の受験者の一人である。彼女は、南雲と坂本の旧友である赤尾リオンの姪にあたる。', 18, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b287914-e3fju4t1fRcv.png', '3月3日', 'A', '市道真央', 164, 287914, 'SUPPORTING', 384) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH013989', 'AN1528', '佐藤田悦子', '引退した暗殺者で、現在はジャパン・クリア・クリエーション（JCC）で教師として暗殺の実技を教えている。サトダは礼儀正しい教師であり、相手をからかうのが好きで、気さくでありながらも淡々とした口調で話す。 彼女は生徒たちを大切にしており、殺し屋になるための指導をしているとはいえ、生徒たちが死ぬことは望んでいない。学生時代、坂本、赤尾リオン、南雲を指導し、今でも彼らを懐かしく思っている。引退した暗殺者とはいえ、里田は若い頃と同じ実力を今も保っている。S', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b288560-erWYRuJ9qfOO.png', NULL, NULL, '渡辺美佐', NULL, 288560, 'SUPPORTING', 27) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH013990', 'AN1529', '大沢綾', '人気者グループの一員で、成績はそれほど良くないが、コミュニケーション能力が高く、友達も多い。学校の男子たちからは人気があるが、彼女自身は彼らには全く興味を示さない。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b282093-KSj41LnAwawO.jpg', '4月16日', NULL, '鬼頭明里', NULL, 282093, 'MAIN', 1101) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH013991', 'AN1529', '古賀美月', '物静かで控えめな性格のため、クラスメートからはアニメオタクと間違われることがある。状況によっては、少しぼんやりしていることもある。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b282094-vAr5cHPwyCIY.jpg', '3月9日', NULL, '伊瀬茉莉也', NULL, 282094, 'MAIN', 1754) ON CONFLICT DO NOTHING;
