INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014003', 'AN1535', 'トラクス', 'トラクスはスキタイ人の奴隷である。彼はテオゲイトンの奴隷であり、テオゲイトンは彼を虐待する場面が何度か登場する。テオゲイトンの発言から、トラクスが奴隷になってまだ日が浅く、そのためまだ従順ではないと推測できる。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b286870-x71Np7CSDa8z.jpg', NULL, NULL, '勝杏里', NULL, 286870, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
