INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014005', 'AN1535', 'カロン', '『ヒストリエ』に登場する脇役。第6章「図書館のロマ（2）」で、エウメネスの奴隷として登場し、彼に同行して学校へ向かった。（出典：ヒストリエWiki）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b128048-qLkN8ScMPv6k.png', NULL, NULL, '高木渉', NULL, 128048, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
