INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014016', 'AN1540', '武村雄介', '他人や社会のことなど全く意に介さない元会社員。なぜか、ゾンビの攻撃を受け付けない特異な体質を持っているが、快楽主義的な性格で、他人を助けることには全く興味がない。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b402400-jGOnzzr1Lrch.png', NULL, NULL, '加藤渉', NULL, 402400, 'MAIN', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014017', 'AN1540', '藤野深月', '彼女は、その際立った美貌と優しい人柄から、常に周囲から愛されてきたが、ゾンビがはびこる世界で両親を亡くしてしまった。生き延び、2人の弟たちを守るために懸命に奮闘する中で、彼女はユウスケと出会う。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b402401-wXgjLxGUMk7i.png', NULL, NULL, '東ゆの', NULL, 402401, 'MAIN', 1) ON CONFLICT DO NOTHING;
