INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014048', 'AN1551', '切谷剛', '彼は、鷲津組の直属組織である黒鳥会の若頭である。会長が服役中のため、現在は組織の暫定的な指揮を執っている。 彼は組織内で最も過激なメンバーである。組長から、リヨの教育と保護を任されている。リヨの性的嗜好には戸惑いを感じつつも、しぶしぶながら彼女を理解し始めている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b403984-gySOtW7qhKJx.png', NULL, NULL, NULL, NULL, 403984, 'MAIN', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014049', 'AN1551', '鷲巣理世', '東京のヤクザ組織「鷲津組」組長の娘。高校生。放課後は部屋に閉じこもりがちで、友達もおらず、内気で物静かな性格だ。 彼女の真の性質は「ヨワラ」（他人が弱っている姿を見て興奮する人）である。性的欲求が暴走しがちな一方で、道徳の枠内に留まりたいという願望も抱いている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b403985-Sh49RGy1t01M.png', NULL, NULL, NULL, NULL, 403985, 'MAIN', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014050', 'AN1552', '六平千鉱', '名匠・六平国重の息子であり、弟子。魔剣「エンテン」の持ち主であり、「白清流」の居合術の達人である。', 18, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b314801-MvuHiyPe5Dxu.png', '8月11日', NULL, '木村太飛', NULL, 314801, 'MAIN', 1061) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014051', 'AN1552', '六平国重', '他に誰も知らない特殊な技法で刀を鍛える名匠。千尋の父。', 37, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b314803-rHxwPh9ehNl9.png', '6月5日', NULL, '関智一', NULL, 314803, 'SUPPORTING', 56) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014052', 'AN1552', '柴登吾', 'かつて「カムナビ」のメンバーであり、セイテイ戦争の退役軍人である六平国重の旧友。', 39, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b314802-MSshYoi5yuJB.jpg', '10月15日', NULL, '小西克幸', NULL, 314802, 'SUPPORTING', 252) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014053', 'AN1554', 'リタ', 'リタは元暗殺者で、現在はエリナの指示のもと「キンダーガーテン・ノワール」で働いている。彼女はダグやハナと共に、タンポポクラスの担任を務めている。  リタは、特に「キンダーガーテン・ノワール」の子供たちと接する際、親しみやすく気さくな性格で知られている。体力に優れているため、子供たちが望むどんな遊びにも難なく参加でき、様々な身体的な遊びにも柔軟に対応できる。一見自信に満ちているように見えるが、', 20, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b289105-XlABZdV3FdQt.png', '4月4日', 'O', '種﨑敦美', 156, 289105, 'MAIN', 158) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014054', 'AN1554', 'ダグ', 'ダグは元詐欺師で、女好きとしても知られている。エリナに「キンダーガーテン・ノワール」での仕事を依頼されるまで、人々を騙して生計を立てていた。現在はリタやハナと共に、タンポポクラスの担任を務めている。ダグは幼い頃から親に捨てられ、一人で生き抜くことを余儀なくされ、過酷な時代を乗り越えてきた。 その結果、彼は強い防衛機制を身につけ、自立心を養い、他人に頼ることなく生き残るためにはどんなことでもやるという決意を固めた。過酷な過去を抱えながらも、ダグには…', 23, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b289106-HZySkLbmkZ1S.jpg', '9月18日', 'A', '熊谷健太郎', 180, 289106, 'MAIN', 71) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014055', 'AN1554', 'ハナ・ブラッドリー', '彼女は爆弾の専門家であり、かつては一族と関わりのあった暗殺者だった。現在は幼稚園の園薗として、リタやダグと共に「タンポポ組」の担任を務めている。', 18, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b293694-2VQMyEmZhaJe.jpg', '2月22日', 'B', '大和田仁美', 153, 293694, 'SUPPORTING', 50) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014056', 'AN1554', 'ルーク・スミス', 'ルークは元イギリス警察官で、現在は「キンダーガーテン・ノワール」の幼稚園教諭として、シルビアと共に「菊組」を担当している。ルークは真面目な性格で、冷たく距離感があるように見えることもあるが、実際には協調性があり、優れたリーダーでもある。彼は幼稚園で最も優秀な新入職員の一人だ。 ルークは、他人のことを傷つけるような言葉を投げかけ、冷たく接することが多い。ルークは少女漫画が大好きで、いつも少女漫画を読んでいる姿が見られ、恋愛に関するアドバイスのほとんどは少女漫画から得ている。', 27, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b310037-tUgbkXtNyjMp.jpg', '12月23日', NULL, '日野聡', 191, 310037, 'SUPPORTING', 84) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014057', 'AN1554', 'シルビア・スコット', '彼女は元密輸業者で、現在は「キンダーガーテン・ノワール」で、ルークやヨシテルと共に「キク組」の担任を務めている。', 24, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b310039-6jNpKSqnyAoJ.jpg', '1月18日', 'B', '伊瀬茉莉也', 170, 310039, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
