INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014068', 'AN1557', 'マハト', 'マハトは悪魔であり、魔王に直属する「七賢者」の一人である。彼は人間の感情を理解し、人間と悪魔が共存できる道を見出したいと願っている。彼はこの目標を達成するため、非人道的な手段を駆使して奮闘している。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b300778-kvoUHowLjexj.png', NULL, NULL, NULL, NULL, 300778, 'SUPPORTING', 271) ON CONFLICT DO NOTHING;